use chrono::{DateTime, Duration, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

use super::{
    Result,
    ports::{DeclarationSource, ImportStore, MemberSource, NotificationQueue, Notifications},
    refresh::{refresh_declarations, refresh_members},
};

#[derive(Clone, Copy, Debug, Deserialize, Serialize)]
#[serde(rename_all = "kebab-case")]
pub(crate) enum ImportKind {
    Members,
    Declarations,
    Initialize,
}

pub(crate) trait Clock: Send + Sync {
    fn now(&self) -> DateTime<Utc>;
}

pub(crate) async fn run_import(
    kind: ImportKind,
    term: NaiveDate,
    as_of: NaiveDate,
    source: &(impl MemberSource + DeclarationSource),
    store: &(impl ImportStore + NotificationQueue),
    clock: &impl Clock,
    notification_interval: Option<i64>,
    scheduled: bool,
) -> Result<Value> {
    let _lease = store.acquire().await?;
    let mut state = store.refresh_state(term).await?;
    let started = clock.now();
    if scheduled && !state.due(started) {
        return Ok(json!({"status":"not-due"}));
    }
    let members = match kind {
        ImportKind::Members | ImportKind::Initialize => {
            Some(refresh_members(term, as_of, source, store).await?)
        }
        ImportKind::Declarations => None,
    };
    if matches!(kind, ImportKind::Members) {
        return Ok(json!(members));
    }
    state.last_attempt = Some(started);
    state.next_attempt = Some(started); // Restart after an interrupted run is immediately due.
    store.record_refresh(term, &state).await?;
    let result = refresh_declarations(term, as_of, source, store).await;
    let ended = clock.now();
    match &result {
        Ok(summary) => state.completed(
            started,
            ended,
            summary.rejected,
            summary.new_members.clone(),
        ),
        Err(_) => state.failed(started, ended),
    }
    store.record_refresh(term, &state).await?;
    if let Err(error) = queue_refresh_notification(term, store, clock, notification_interval).await
    {
        eprintln!("Could not queue import notification: {error:?}");
    }
    let declarations = result?;
    Ok(if matches!(kind, ImportKind::Initialize) {
        json!({"status":"succeeded", "members":members, "declarations":declarations})
    } else {
        json!(declarations)
    })
}

pub(crate) async fn deliver_pending(
    queue: &impl NotificationQueue,
    notifications: &impl Notifications,
    clock: &impl Clock,
) -> Result<()> {
    if let Some((id, message, attempts)) = queue.pending(clock.now()).await? {
        match notifications.deliver(&message).await {
            Ok(()) => queue.delivered(id).await?,
            Err(error) => {
                eprintln!("Notification delivery failed: {error:?}");
                let seconds = 60_i64
                    .saturating_mul(2_i64.saturating_pow(attempts.clamp(0, 6) as u32))
                    .min(3600);
                queue
                    .retry_notification(id, clock.now() + Duration::seconds(seconds))
                    .await?;
            }
        }
    }
    Ok(())
}

// Retrying this operation is safe after queue storage failures: the interval key is unique.
pub(crate) async fn queue_refresh_notification(
    term: NaiveDate,
    store: &(impl ImportStore + NotificationQueue),
    clock: &impl Clock,
    interval: Option<i64>,
) -> Result<()> {
    let Some(interval) = interval.filter(|seconds| *seconds > 0) else {
        return Ok(());
    };
    let state = store.refresh_state(term).await?;
    let Some(outcome) = &state.outcome else {
        return Ok(());
    };
    let bucket = clock.now().timestamp().div_euclid(interval);
    let key = format!("refresh:{term}:{bucket}");
    let message = format!(
        "Exposed refresh: {outcome}. Last complete source check: {}. Rejected declarations: {}. New MPs awaiting manual refresh: {:?}.",
        state
            .last_completed
            .map_or_else(|| "never".into(), |d| d.to_rfc3339()),
        state.rejected,
        state.new_members
    );
    store.enqueue(&key, &message).await
}
//! Composition and lifecycle for source workers, operator API, and timers.
use anyhow::Context;
use chrono::{DateTime, Utc};
use sqlx::postgres::PgPoolOptions;
use std::{sync::Arc, time::Duration};

use super::{
    adapters::{
        parliament::{CliTransport, Parliament},
        postgres::PostgresStore,
        whatsapp::WhatsApp,
    },
    admin::{self, AdminState},
    config::ImportConfig,
    core::{
        ImportError,
        coordinator::{Clock, ImportKind, deliver_pending, queue_refresh_notification, run_import},
        ports::ImportStore,
    },
};

pub(crate) struct SystemClock;
impl Clock for SystemClock {
    fn now(&self) -> DateTime<Utc> {
        Utc::now()
    }
}

/// Run the import operator listener and the in-process daily refresh task.
///
/// # Errors
/// Returns a configuration, database connection, or listener error at startup.
/// Migrations remain an explicit operator action.
pub async fn serve(config: &ImportConfig, connection_string: &str) -> anyhow::Result<()> {
    let token = config
        .admin_token_env
        .as_ref()
        .map(|name| std::env::var(name))
        .transpose()
        .context("Operator token environment variable is missing")?;
    anyhow::ensure!(
        token.as_ref().is_none_or(|t| !t.is_empty()),
        "Operator token is empty"
    );
    anyhow::ensure!(
        config.admin_bind.ip().is_loopback() || token.is_some(),
        "A non-loopback operator listener requires an access token"
    );
    anyhow::ensure!(
        config.notification_interval_seconds.is_none_or(|n| n > 0),
        "Notification interval must be positive"
    );
    anyhow::ensure!(
        config.notification_interval_seconds.is_none() || config.whatsapp.is_some(),
        "A notification interval requires a WhatsApp adapter"
    );
    let whatsapp = config.whatsapp.clone().map(WhatsApp::new).transpose()?;
    let pool = PgPoolOptions::new()
        .max_connections(8)
        .acquire_timeout(Duration::from_secs(15))
        .connect(connection_string)
        .await?;
    let store = PostgresStore::new(pool);
    store.refresh_state(config.term_start).await?;
    let config = Arc::new(config.clone());
    let state = AdminState::new(store.clone(), config.clone(), token);
    let listener = tokio::net::TcpListener::bind(config.admin_bind).await?;
    let server = async {
        axum::serve(listener, admin::router(state.clone()))
            .await
            .map_err(anyhow::Error::from)
    };
    let refresh = async {
        let mut timer = tokio::time::interval(Duration::from_secs(60));
        timer.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            timer.tick().await;
            state.expire_sessions().await;
            if !config.automatic_refresh {
                continue;
            }
            let result = async {
                if !store
                    .refresh_state(config.term_start)
                    .await?
                    .due(Utc::now())
                {
                    return Ok(());
                }
                let source = Parliament(CliTransport::new(
                    config.python.clone(),
                    config.source_directory.clone(),
                ));
                let as_of = Utc::now()
                    .with_timezone(&chrono_tz::Europe::London)
                    .date_naive();
                run_import(
                    ImportKind::Declarations,
                    config.term_start,
                    as_of,
                    &source,
                    &store,
                    &SystemClock,
                    config.notification_interval_seconds,
                    true,
                )
                .await?;
                Ok::<_, ImportError>(())
            }
            .await;
            if let Err(error) = result {
                if !matches!(error, ImportError::Busy) {
                    eprintln!("Scheduled declaration refresh: {error:?}");
                }
            }
        }
        #[allow(unreachable_code)]
        Ok::<(), anyhow::Error>(())
    };
    let notifications = async {
        let mut timer = tokio::time::interval(Duration::from_secs(30));
        timer.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            timer.tick().await;
            if let Some(adapter) = &whatsapp {
                if let Err(error) = queue_refresh_notification(
                    config.term_start,
                    &store,
                    &SystemClock,
                    config.notification_interval_seconds,
                )
                .await
                {
                    eprintln!("Notification policy: {error:?}");
                }
                if let Err(error) = deliver_pending(&store, adapter, &SystemClock).await {
                    eprintln!("Notification queue: {error:?}");
                }
            }
        }
        #[allow(unreachable_code)]
        Ok::<(), anyhow::Error>(())
    };
    tokio::try_join!(server, refresh, notifications)?;
    Ok(())
}
//! Operator HTTP adapter. Source commands are generated by the Rust Parliament adapter.
use axum::{
    Json, Router,
    extract::{DefaultBodyLimit, Path, State},
    http::{HeaderMap, StatusCode},
    routing::{get, post},
};
use chrono::NaiveDate;
use serde::Deserialize;
use serde_json::{Value, json};
use std::{
    collections::HashMap,
    sync::Arc,
    time::{Duration, Instant},
};
use tokio::{
    sync::{Mutex, mpsc, oneshot},
    task::JoinHandle,
};
use uuid::Uuid;

use super::{
    adapters::{
        parliament::{Parliament, Request, Response, Transport},
        postgres::PostgresStore,
    },
    config::ImportConfig,
    core::{
        ImportError, Result,
        coordinator::{ImportKind, run_import},
        ports::ImportStore,
    },
    runtime::SystemClock,
};

enum Event {
    Fetch(Request, oneshot::Sender<Response>),
    Finished(Value),
}
struct RemoteTransport(mpsc::Sender<Event>);
impl Transport for RemoteTransport {
    async fn fetch(&self, request: Request) -> Result<Response> {
        let (tx, rx) = oneshot::channel();
        self.0
            .send(Event::Fetch(request, tx))
            .await
            .map_err(|e| ImportError::source_failure("Operator disconnected", e))?;
        tokio::time::timeout(Duration::from_secs(300), rx)
            .await
            .map_err(|e| ImportError::source_failure("Operator source session expired", e))?
            .map_err(|e| ImportError::source_failure("Operator disconnected", e))
    }
}
struct Session {
    task: JoinHandle<()>,
    exchange: Mutex<Exchange>,
}
struct RegisteredSession {
    session: Arc<Session>,
    touched: Instant,
}
impl RegisteredSession {
    fn retain_unexpired(&self) -> bool {
        if self.touched.elapsed() >= Duration::from_secs(900) {
            self.session.task.abort();
            return false;
        }
        true
    }
}
struct Exchange {
    events: mpsc::Receiver<Event>,
    pending: Option<oneshot::Sender<Response>>,
    sequence: u64,
    last_submission: Option<Value>,
    message: Option<Value>,
}
impl Drop for Session {
    fn drop(&mut self) {
        self.task.abort();
    }
}
impl Exchange {
    async fn message(&mut self) -> Value {
        if let Some(message) = &self.message {
            return message.clone();
        }
        let message = match self.events.recv().await {
            Some(Event::Fetch(request, reply)) => {
                self.pending = Some(reply);
                json!({"sequence":self.sequence,"request":request})
            }
            Some(Event::Finished(result)) => result,
            None => json!({"error":"Import task stopped; retry the import"}),
        };
        self.message = Some(message.clone());
        message
    }
}

#[derive(Clone)]
pub(crate) struct AdminState {
    store: PostgresStore,
    config: Arc<ImportConfig>,
    token: Option<String>,
    sessions: Arc<Mutex<HashMap<Uuid, RegisteredSession>>>,
}
impl AdminState {
    pub fn new(store: PostgresStore, config: Arc<ImportConfig>, token: Option<String>) -> Self {
        Self {
            store,
            config,
            token,
            sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }
    fn authorize(&self, headers: &HeaderMap) -> std::result::Result<(), (StatusCode, Json<Value>)> {
        if let Some(token) = &self.token {
            if headers.get("authorization").and_then(|h| h.to_str().ok())
                != Some(format!("Bearer {token}").as_str())
            {
                return Err((
                    StatusCode::UNAUTHORIZED,
                    Json(json!({"error":"Invalid operator token"})),
                ));
            }
        }
        Ok(())
    }
    pub async fn expire_sessions(&self) {
        self.sessions
            .lock()
            .await
            .retain(|_, session| session.retain_unexpired());
    }
}

type HttpResult = std::result::Result<Json<Value>, (StatusCode, Json<Value>)>;
fn bad(status: StatusCode, message: &str) -> (StatusCode, Json<Value>) {
    (status, Json(json!({"error":message})))
}

#[derive(Deserialize)]
struct Begin {
    kind: ImportKind,
    term_start: Option<NaiveDate>,
}

async fn begin(
    State(state): State<AdminState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(body): Json<Begin>,
) -> HttpResult {
    state.authorize(&headers)?;
    let term = body.term_start.unwrap_or(state.config.term_start);
    if term != state.config.term_start {
        return Err(bad(
            StatusCode::UNPROCESSABLE_ENTITY,
            "Term differs from the Rust application configuration",
        ));
    }
    let mut sessions = state.sessions.lock().await;
    sessions.retain(|_, session| session.retain_unexpired());
    if let Some(session) = sessions.get_mut(&id) {
        session.touched = Instant::now();
        let session = Arc::clone(&session.session);
        drop(sessions);
        let message = session.exchange.lock().await.message().await;
        return Ok(Json(message));
    }
    if sessions.len() >= 32 {
        return Err(bad(
            StatusCode::TOO_MANY_REQUESTS,
            "Too many import sessions; retry later",
        ));
    }
    let (tx, events) = mpsc::channel(1);
    let store = state.store.clone();
    let interval = state.config.notification_interval_seconds;
    let task = tokio::spawn(async move {
        let source = Parliament(RemoteTransport(tx.clone()));
        let as_of = chrono::Utc::now()
            .with_timezone(&chrono_tz::Europe::London)
            .date_naive();
        let result = run_import(
            body.kind,
            term,
            as_of,
            &source,
            &store,
            &SystemClock,
            interval,
            false,
        )
        .await;
        let message = match result {
            Ok(result) => json!({"result":result}),
            Err(error) => {
                eprintln!("Operator import: {error:?}");
                json!({"error":error.to_string()})
            }
        };
        let _ = tx.send(Event::Finished(message)).await;
    });
    let session = Arc::new(Session {
        task,
        exchange: Mutex::new(Exchange {
            events,
            pending: None,
            sequence: 0,
            last_submission: None,
            message: None,
        }),
    });
    sessions.insert(
        id,
        RegisteredSession {
            session: Arc::clone(&session),
            touched: Instant::now(),
        },
    );
    drop(sessions);
    let message = session.exchange.lock().await.message().await;
    Ok(Json(message))
}

#[derive(Deserialize)]
struct Submission {
    sequence: u64,
    response: Response,
}
async fn evidence(
    State(state): State<AdminState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(body): Json<Submission>,
) -> HttpResult {
    state.authorize(&headers)?;
    let mut sessions = state.sessions.lock().await;
    let session = sessions.get_mut(&id).ok_or_else(|| {
        bad(
            StatusCode::NOT_FOUND,
            "Import session expired; rerun safely",
        )
    })?;
    session.touched = Instant::now();
    let session = Arc::clone(&session.session);
    drop(sessions);
    let mut session = session.exchange.lock().await;
    let raw = json!(body.response);
    if body.sequence.checked_add(1) == Some(session.sequence)
        && session.last_submission.as_ref() == Some(&raw)
    {
        return Ok(Json(session.message().await));
    }
    if body.sequence != session.sequence {
        return Err(bad(StatusCode::CONFLICT, "Unexpected evidence sequence"));
    }
    let reply = session
        .pending
        .take()
        .ok_or_else(|| bad(StatusCode::CONFLICT, "No evidence requested"))?;
    reply
        .send(body.response)
        .map_err(|_| bad(StatusCode::GONE, "Import source session expired"))?;
    session.sequence += 1;
    session.last_submission = Some(raw);
    session.message = None;
    Ok(Json(session.message().await))
}

async fn cancel(
    State(state): State<AdminState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
) -> HttpResult {
    state.authorize(&headers)?;
    if let Some(session) = state.sessions.lock().await.remove(&id) {
        // The exchange may be waiting on publication. Abort without taking that lock.
        session.session.task.abort();
    }
    Ok(Json(json!({"status":"cancelled"})))
}
async fn status(State(state): State<AdminState>, headers: HeaderMap) -> HttpResult {
    state.authorize(&headers)?;
    let refresh = state
        .store
        .refresh_state(state.config.term_start)
        .await
        .map_err(|error| {
            eprintln!("Import status: {error:?}");
            bad(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Could not read refresh state",
            )
        })?;
    Ok(Json(json!(refresh)))
}

pub(crate) fn router(state: AdminState) -> Router {
    Router::new()
        .route("/imports/status", get(status))
        .route("/imports/{id}", post(begin).delete(cancel))
        .route("/imports/{id}/evidence", post(evidence))
        .layer(DefaultBodyLimit::max(32 * 1024 * 1024))
        .with_state(state)
}

