fn invalid_and_conflicting_service_histories_are_rejected() {
    let term = date("2024-07-04");
    for memberships in [
        vec![HouseMembership {
            house: 1,
            start: date("2025-06-01"),
            end: Some(date("2025-05-01")),
        }],
        vec![
