struct Worker {
    _child: Child,
    input: ChildStdin,
    output: BufReader<ChildStdout>,
}
pub(crate) struct CliTransport {
    python: PathBuf,
    directory: PathBuf,
    worker: Mutex<Option<Worker>>,
}

impl CliTransport {
    pub fn new(python: PathBuf, directory: PathBuf) -> Self {
        Self {
            python,
            directory,
            worker: Mutex::new(None),
        }
    }
    fn start(&self) -> Result<Worker> {
        // Preserve the venv executable symlink: resolving it selects the base Python.
        let python = std::path::absolute(&self.python)
            .map_err(|e| ImportError::source_failure("Python executable is unavailable", e))?;
        let mut command = Command::new(python);
        command
            .args(["-m", "exposed", "source"])
            .current_dir(&self.directory)
            .env_clear()
            .env("PYTHONPATH", "src")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .kill_on_drop(true);
        for key in [
            "PATH",
            "SSL_CERT_FILE",
            "HTTPS_PROXY",
            "HTTP_PROXY",
            "NO_PROXY",
        ] {
            if let Some(value) = std::env::var_os(key) {
                command.env(key, value);
            }
        }
        let mut child = command
            .spawn()
            .map_err(|e| ImportError::source_failure("Could not start Python API worker", e))?;
        let input = child
            .stdin
            .take()
            .ok_or_else(|| ImportError::Source("Worker stdin unavailable".into()))?;
        let output = BufReader::new(
            child
                .stdout
                .take()
                .ok_or_else(|| ImportError::Source("Worker stdout unavailable".into()))?,
        );
        Ok(Worker {
            _child: child,
            input,
            output,
        })
    }
}

impl Transport for CliTransport {
    async fn fetch(&self, request: Request) -> Result<Response> {
        tokio::time::timeout(Duration::from_secs(240), async {
            let mut slot = self.worker.lock().await;
            if slot.is_none() {
                *slot = Some(self.start()?);
            }
            let worker = slot
                .as_mut()
                .ok_or_else(|| ImportError::Source("Worker did not start".into()))?;
            let mut data = serde_json::to_vec(&request)
                .map_err(|e| ImportError::source_failure("Could not encode worker request", e))?;
            data.push(b'\n');
            worker
                .input
                .write_all(&data)
                .await
                .map_err(|e| ImportError::source_failure("Worker input closed", e))?;
            worker
                .input
                .flush()
                .await
                .map_err(|e| ImportError::source_failure("Worker input closed", e))?;
            let mut line = String::new();
            worker
                .output
                .read_line(&mut line)
                .await
                .map_err(|e| ImportError::source_failure("Worker output closed", e))?;
            let value: Value = serde_json::from_str(&line)
                .map_err(|e| ImportError::source_failure("Invalid worker response", e))?;
            if let Some(error) = value.get("error").and_then(Value::as_str) {
                return Err(ImportError::Source(error.to_owned()));
            }
            serde_json::from_value(value)
                .map_err(|e| ImportError::source_failure("Invalid evidence envelope", e))
        })
        .await
        .map_err(|e| ImportError::source_failure("Python API worker timed out", e))?
    }
}
"""Submit source evidence and wait for Rust's next request or committed result."""

import logging
import time
from typing import Any
from uuid import uuid4

import httpx

from exposed.source import SourceClient


class OperatorError(Exception):
    """The Rust application could not complete the import."""


def _post(app: httpx.Client, path: str, body: dict[str, Any]) -> dict[str, Any]:
    # Same session/sequence/body on every retry: a lost acknowledgement must not
    # publish a batch twice or start a second run.
    for attempt in range(3):
        try:
            response = app.post(path, json=body)
        except httpx.TransportError:
            if attempt == 2:
                raise OperatorError("Cannot reach the Rust import interface") from None
            time.sleep(2**attempt)
            continue
        try:
            message = response.json()
        except ValueError:
            raise OperatorError(
                f"Rust returned an invalid response (HTTP {response.status_code})"
            ) from None
        if not isinstance(message, dict):
            raise OperatorError("Rust returned an invalid response envelope")
        if not response.is_success or "error" in message:
            raise OperatorError(message.get("error", f"Rust returned HTTP {response.status_code}"))
        return message
    raise OperatorError("Rust request retries exhausted")


def run_import(
    kind: str, term_start: str | None, app: httpx.Client, source: SourceClient
) -> dict[str, Any]:
    path = f"/imports/{uuid4()}"
    try:
        message = _post(app, path, {"kind": kind, "term_start": term_start})
        while "request" in message:
            evidence = source.fetch(message["request"])
            message = _post(
                app, path + "/evidence", {"sequence": message["sequence"], "response": evidence}
            )
        if not isinstance(message.get("result"), dict):
            raise OperatorError("Rust response has no import result")
        return message["result"]
    finally:
        try:
            app.delete(path, timeout=5)
        except httpx.HTTPError:
            logging.warning("Unable to close import session; it will expire automatically")
