use super::{ImportError, Result};

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub(crate) struct Funding {
    pub funder_name: Option<String>,
    pub funder_kind: Option<String>,
    pub company_number: Option<String>,
    pub amount: Option<BigDecimal>,
    pub currency: Option<String>,
    pub payment_type: Option<String>,
}

#[derive(Clone, Debug, Serialize)]
pub(crate) struct Draft {
    pub id: i32,
    pub member_source_id: i32,
    pub category_id: i32,
    pub category_name: String,
    pub registration_date: Option<NaiveDate>,
    pub funding: Vec<Funding>,
    pub payer: Option<String>,
    pub parent_id: Option<i32>,
    pub ultimate_payer_differs: bool,
}

#[derive(Clone, Debug)]
pub(crate) struct Declaration {
    draft: Draft,
}

impl Declaration {
    pub fn draft(&self) -> &Draft {
        &self.draft
    }
}

impl Draft {
    pub fn required_parent(&self) -> Option<i32> {
        self.parent_id.filter(|_| {
            !self.ultimate_payer_differs
                && (self.funding.iter().any(|f| f.funder_name.is_none())
                    || (self.funding.is_empty() && self.payer.is_none()))
        })
    }

    pub fn accept(mut self, parent: Option<&Declaration>) -> Result<Declaration> {
        if self.id <= 0
            || self.member_source_id <= 0
            || self.category_id <= 0
            || self.category_name.trim().is_empty()
        {
            return Err(ImportError::Rejected("Invalid declaration identity".into()));
        }
        if let Some(parent_id) = self.required_parent() {
            let parent = parent
                .ok_or_else(|| ImportError::Rejected("Required parent was not returned".into()))?;
            if parent.draft.id != parent_id
                || parent.draft.member_source_id != self.member_source_id
            {
                return Err(ImportError::Rejected(
                    "Parent identity or member mismatch".into(),
                ));
            }
            let payer =
                parent.draft.payer.as_ref().ok_or_else(|| {
                    ImportError::Rejected("Required parent payer is absent".into())
                })?;
            self.payer.get_or_insert_with(|| payer.clone());
            for entry in &mut self.funding {
                entry.funder_name.get_or_insert_with(|| payer.clone());
            }
        }
        Ok(Declaration { draft: self })
    }
}

// Source alias decoding belongs to the adapter; attribution order belongs here.
pub(crate) struct FunderCandidates {
    pub ultimate_payer: Result<Option<String>>,
    pub donor: Result<Option<String>>,
    pub payer: Result<Option<String>>,
    pub group_donor: Result<Option<String>>,
}

impl FunderCandidates {
    fn preferred(self) -> Result<Option<String>> {
        for candidate in [
            self.ultimate_payer,
            self.donor,
            self.payer,
            self.group_donor,
        ] {
            if let Some(name) = candidate? {
                return Ok(Some(normalize_funder(&name)));
            }
        }
        Ok(None)
    }
}

// Decoding errors in unused fallback names/metadata must not reject an attribution.
pub(crate) fn funder_attribution(
    candidates: FunderCandidates,
    donor_status: Result<Option<String>>,
    donor_number: Result<Option<String>>,
) -> Result<(Option<String>, Option<String>, Option<String>)> {
    let donor = match &candidates.donor {
        Ok(None) => candidates
            .group_donor
            .as_ref()
            .ok()
            .and_then(|name| name.as_ref()),
        Ok(Some(name)) => Some(name),
        Err(_) => None,
    }
    .map(|name| normalize_funder(name));
    let funder = candidates.preferred()?;
    let kind = if funder == donor { donor_status? } else { None };
    let number = if kind.as_deref() == Some("Company") {
        donor_number?
    } else {
        None
    };
    Ok((funder, kind, number))
}

pub(crate) fn normalize_funder(name: &str) -> String {
    let lowered = name.to_lowercase();
    let value = lowered.trim();
    for suffix in ["limited", "ltd.", "ltd"] {
        if let Some(prefix) = value.strip_suffix(suffix) {
            if prefix.is_empty() || prefix.ends_with(char::is_whitespace) {
                return format!("{prefix}ltd");
            }
        }
    }
    value.to_owned()
}

pub(crate) fn latest_version(versions: &[(NaiveDate, Value)]) -> Result<usize> {
    let newest =
        versions.iter().map(|v| v.0).max().ok_or_else(|| {
            ImportError::Rejected("Expected at least one published version".into())
        })?;
    let indices: Vec<_> = versions
        .iter()
        .enumerate()
        .filter(|(_, v)| v.0 == newest)
        .map(|(i, _)| i)
        .collect();
    let first = indices[0];
    if indices.iter().any(|i| versions[*i].1 != versions[first].1) {
        return Err(ImportError::Rejected(
            "Conflicting versions at latest register date".into(),
        ));
    }
    Ok(first)
}

#[derive(Clone, Debug)]
pub(crate) struct Evidence {
    pub source_id: Option<i32>,
    pub payload: Value,
    pub fetched_at: DateTime<Utc>,
    pub context: String,
}

impl Evidence {
    pub fn id(&self) -> Option<i32> {
        self.source_id
    }
}

#[derive(Clone, Debug)]
pub(crate) struct Accepted {
    pub declaration: Declaration,
    pub fetched_at: DateTime<Utc>,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub(crate) struct Payment {
    pub funder_id: Option<Uuid>,
    pub amount: Option<BigDecimal>,
    pub currency: Option<String>,
    pub payment_type: Option<String>,
}

pub(crate) fn same_payments(left: &[Payment], right: &[Payment]) -> bool {
    fn counts(values: &[Payment]) -> HashMap<&Payment, usize> {
        let mut counts = HashMap::new();
        for value in values {
            *counts.entry(value).or_default() += 1;
        }
        counts
    }
    counts(left) == counts(right)
}

// An omission retains metadata. An explicit non-company correction clears its number.
pub(crate) fn merge_funder_metadata(
    incoming: &Funding,
    previous_kind: Option<String>,
    previous_number: Option<String>,
) -> (Option<String>, Option<String>) {
    let kind = incoming.funder_kind.clone().or(previous_kind);
    let number = if kind.as_deref() == Some("Company") {
        incoming.company_number.clone().or(previous_number)
    } else {
        None
    };
    (kind, number)
}
use std::{collections::HashMap, str::FromStr};

use bigdecimal::BigDecimal;
use chrono::{DateTime, NaiveDate, NaiveDateTime};
use serde::Deserialize;
use serde_json::{Map, Value};

use crate::imports::core::{
    ImportError, Result,
    declarations::{Draft, FunderCandidates, Funding, funder_attribution, latest_version},
};

pub(crate) fn invalid(path: &str, value: &Value, message: &str) -> ImportError {
    ImportError::Rejected(format!("{path}: {message}; input={value}"))
}

pub(crate) fn source_date(value: &Value, path: &str) -> Result<NaiveDate> {
    let text = value
        .as_str()
        .ok_or_else(|| invalid(path, value, "expected an ISO date"))?;
    if let Ok(date) = NaiveDate::parse_from_str(text, "%Y-%m-%d") {
        return Ok(date);
    }
    if let Ok(date) = DateTime::parse_from_rfc3339(text) {
        return Ok(date.date_naive());
    }
    for format in ["%Y-%m-%dT%H:%M:%S%.f", "%Y-%m-%d %H:%M:%S%.f"] {
        if let Ok(date) = NaiveDateTime::parse_from_str(text, format) {
            return Ok(date.date());
        }
    }
    Err(invalid(path, value, "expected an ISO date or datetime"))
}

fn positive(value: &Value, path: &str) -> Result<i32> {
    value
        .as_i64()
        .and_then(|n| i32::try_from(n).ok())
        .filter(|n| *n > 0)
        .ok_or_else(|| invalid(path, value, "expected a positive integer"))
}

fn nonblank(value: &Value, path: &str) -> Result<String> {
    value
        .as_str()
        .filter(|s| !s.trim().is_empty())
        .map(str::to_owned)
        .ok_or_else(|| invalid(path, value, "expected a nonblank string"))
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Field {
    name: String,
    #[serde(rename = "type")]
    kind: Option<String>,
    type_info: Option<Map<String, Value>>,
    #[serde(default)]
    value: Value,
    values: Option<Vec<Vec<Field>>>,
}

impl Field {
    fn text(&self, path: &str) -> Result<Option<String>> {
        if self.value.is_null() {
            return Ok(None);
        }
        self.value
            .as_str()
            .map(|s| (!s.trim().is_empty()).then(|| s.to_owned()))
            .ok_or_else(|| invalid(path, &self.value, "expected a string"))
    }

    fn check_shape(&self, path: &str, allowed: bool, nested: bool) -> Result<()> {
        let currency = self
            .type_info
            .as_ref()
            .is_some_and(|m| m.contains_key("currencyCode"));
        let financial =
            ["Value", "PaymentType", "Donors"].contains(&self.name.as_str()) || currency;
        if financial
            && (!allowed || (currency && self.name != "Value") || (nested && self.name == "Donors"))
        {
            return Err(invalid(
                path,
                &self.value,
                "unsupported funding field or nesting",
            ));
        }
        for (i, group) in self.values.iter().flatten().enumerate() {
            if self.name == "Donors" && group.is_empty() {
                return Err(invalid(path, &self.value, "empty donor group"));
            }
            for (j, field) in group.iter().enumerate() {
                field.check_shape(
                    &format!("{path}.values.{i}.{j}.{}", field.name),
                    allowed && self.name == "Donors",
                    true,
                )?;
            }
        }
        Ok(())
    }
}

fn funding(fields: &[Field], path: &str, donor_group: bool) -> Result<Funding> {
    let index: HashMap<_, _> = fields
        .iter()
        .enumerate()
        .map(|(i, f)| (f.name.as_str(), (i, f)))
        .collect();
    if index.len() != fields.len() {
        return Err(ImportError::Rejected(format!(
            "{path}: repeated field names"
        )));
    }
    let text = |name: &str| -> Result<Option<String>> {
        match index.get(name) {
            Some((i, f)) => f.text(&format!("{path}.{i}.{name}.value")),
            None => Ok(None),
        }
    };
    let mut amount = None;
    let mut currency = None;
    if let Some((i, value)) = index.get("Value") {
        let location = format!("{path}.{i}.Value");
        if value.kind.as_deref() != Some("Decimal") {
            return Err(invalid(
                &location,
                &value.value,
                "expected Decimal monetary field",
            ));
        }
        if !value.value.is_null() {
            let raw = match &value.value {
                Value::String(text) => text.clone(),
                Value::Number(number) => {
                    let raw = number.to_string();
                    // Python accepts arbitrary-size JSON integers, but rejects JSON floats.
                    if raw.contains(['.', 'e', 'E']) {
                        return Err(invalid(&location, &value.value, "unsupported amount"));
                    }
                    raw
                }
                _ => return Err(invalid(&location, &value.value, "unsupported amount")),
            };
            let unsigned = raw.strip_prefix('-').unwrap_or(&raw);
            let parts: Vec<_> = unsigned.split('.').collect();
            if parts.len() > 2
                || parts
                    .iter()
                    .any(|p| p.is_empty() || !p.bytes().all(|c| c.is_ascii_digit()))
            {
                return Err(invalid(&location, &value.value, "unsupported amount"));
            }
            amount = Some(
                BigDecimal::from_str(&raw)
                    .map_err(|_| invalid(&location, &value.value, "unsupported amount"))?,
            );
        }
        if let Some(code) = value
            .type_info
            .as_ref()
            .and_then(|m| m.get("currencyCode"))
            .filter(|v| !v.is_null())
        {
            currency = Some(
                code.as_str()
                    .ok_or_else(|| invalid(&location, code, "expected a currency string"))?
                    .to_owned(),
            );
        }
    }
    let (funder_name, funder_kind, company_number) = funder_attribution(
        FunderCandidates {
            ultimate_payer: text("UltimatePayerName"),
            donor: text("DonorName"),
            payer: text("PayerName"),
            group_donor: if donor_group { text("Name") } else { Ok(None) },
        },
        text("DonorStatus"),
        text("DonorCompanyIdentifier"),
    )?;
    Ok(Funding {
        funder_name,
        funder_kind,
        company_number,
        amount,
        currency,
        payment_type: text("PaymentType")?,
    })
}

pub(crate) fn interpret(raw: &Value) -> Result<Draft> {
    let id = positive(&raw["id"], "id")?;
    let member_source_id = positive(
        &raw["registrant"]["memberDetail"]["id"],
        "registrant.memberDetail.id",
    )?;
    if raw["registrant"]["type"] != "Member" || raw["category"]["type"] != "Commons" {
        return Err(invalid(
            "registrant/category",
            raw,
            "expected a Commons Member declaration",
        ));
    }
    let category_id = positive(&raw["category"]["id"], "category.id")?;
    let category_name = nonblank(&raw["category"]["name"], "category.name")?;
    let parent_id = if raw["parentInterestId"].is_null() {
        None
    } else {
        Some(positive(&raw["parentInterestId"], "parentInterestId")?)
    };
    let versions = raw["versions"]
        .as_array()
        .ok_or_else(|| invalid("versions", &raw["versions"], "expected versions"))?;
    let published = versions
        .iter()
        .enumerate()
        .map(|(i, v)| {
            let date = source_date(
                &v["register"]["publishedDate"],
                &format!("versions.{i}.register.publishedDate"),
            )?;
            let mut content = v
                .as_object()
                .ok_or_else(|| invalid("versions", v, "expected version object"))?
                .clone();
            content.remove("register");
            content.remove("links");
            Ok((date, Value::Object(content)))
        })
        .collect::<Result<Vec<_>>>()?;
    let selected = latest_version(&published)?;
    let version = &versions[selected];
    let path = format!("versions.{selected}.fields");
    let fields: Vec<Field> = serde_json::from_value(version["fields"].clone())
        .map_err(|e| invalid(&path, &version["fields"], &e.to_string()))?;
    let mut entries = Vec::new();
    for (i, field) in fields.iter().enumerate() {
        field.check_shape(&format!("{path}.{i}.{}", field.name), true, false)?;
    }
    if fields
        .iter()
        .any(|f| ["Value", "PaymentType"].contains(&f.name.as_str()))
    {
        entries.push(funding(&fields, &path, false)?);
    }
    for (i, field) in fields
        .iter()
        .enumerate()
        .filter(|(_, f)| f.name == "Donors")
    {
        let groups = field
            .values
            .as_ref()
            .ok_or_else(|| invalid(&path, &field.value, "expected donor groups"))?;
        for (j, group) in groups.iter().enumerate() {
            entries.push(funding(
                group,
                &format!("{path}.{i}.Donors.values.{j}"),
                true,
            )?);
        }
    }
    let payer = funding(&fields, &path, false)?.funder_name;
    let mut ultimate_payer_differs = false;
    if parent_id.is_some() {
        if let Some(field) = fields.iter().find(|f| f.name == "IsUltimatePayerDifferent") {
            if !field.value.is_null() && !field.value.is_boolean() {
                return Err(invalid(&path, &field.value, "expected a boolean"));
            }
            ultimate_payer_differs = field.value == true;
        }
    }
    let registration_date = if version["registrationDate"].is_null() {
        None
    } else {
        Some(source_date(
            &version["registrationDate"],
            "registrationDate",
        )?)
    };
    Ok(Draft {
        id,
        member_source_id,
        category_id,
        category_name,
        registration_date,
        funding: entries,
        payer,
        parent_id,
        ultimate_payer_differs,
    })
}
use chrono::NaiveDate;

use super::{ImportError, Result};

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct HouseMembership {
    pub house: i16,
    pub start: NaiveDate,
    pub end: Option<NaiveDate>,
}

#[derive(Clone, Debug)]
pub(crate) struct MemberHistory {
    pub id: i32,
    pub memberships: Vec<HouseMembership>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct ServicePeriod {
    pub source_start: NaiveDate,
    pub served_from: NaiveDate,
    pub end: Option<NaiveDate>,
}

impl MemberHistory {
    pub fn service(
        &self,
        term: NaiveDate,
        as_of: NaiveDate,
        current: bool,
    ) -> Result<Vec<ServicePeriod>> {
        let mut periods: Vec<_> = self
            .memberships
            .iter()
            .filter(|m| m.house == 1 && m.start <= as_of && m.end.is_none_or(|end| end > term))
            .map(|m| ServicePeriod {
                source_start: m.start,
                served_from: m.start.max(term),
                end: m.end,
            })
            .collect();
        periods.sort_by_key(|p| p.source_start);
        periods.dedup();
        if periods
            .iter()
            .any(|p| p.end.is_some_and(|end| end < p.served_from))
        {
            return Err(ImportError::Invalid(format!(
                "Member {}: service ends before it starts",
                self.id
            )));
        }
        for pair in periods.windows(2) {
            if pair[0].source_start == pair[1].source_start
                || pair[0].end.is_none_or(|end| pair[1].served_from < end)
            {
                return Err(ImportError::Invalid(format!(
                    "Member {}: conflicting or overlapping service periods",
                    self.id
                )));
            }
        }
        if periods.iter().any(|p| p.end.is_none_or(|end| end > as_of)) != current {
            return Err(ImportError::Invalid(format!(
                "Member {}: history disagrees with current search",
                self.id
            )));
        }
        Ok(periods)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct MemberProfile {
    pub id: i32,
    pub name: String,
    pub party_id: Option<i32>,
    pub party_name: Option<String>,
    pub house: i16,
    pub membership_from: Option<String>,
}

impl MemberProfile {
    pub fn validate(&self) -> Result<()> {
        if self.id <= 0
            || self.name.trim().is_empty()
            || ![1, 2].contains(&self.house)
            || self.party_id.is_some_and(|id| id <= 0)
        {
            return Err(ImportError::Invalid("Invalid member profile".into()));
        }
        Ok(())
    }
}

#[derive(Clone, Debug)]
pub(crate) struct Member {
    profile: MemberProfile,
    current: bool,
    periods: Vec<ServicePeriod>,
}

impl Member {
    pub fn profile(&self) -> &MemberProfile {
        &self.profile
    }
    pub fn is_current(&self) -> bool {
        self.current
    }
    pub fn periods(&self) -> &[ServicePeriod] {
        &self.periods
    }
    pub fn from_history(
        profile: MemberProfile,
        history: &MemberHistory,
        term: NaiveDate,
        as_of: NaiveDate,
        current: bool,
    ) -> Result<Self> {
        profile.validate()?;
        if profile.id != history.id || (current && profile.house != 1) {
            return Err(ImportError::Invalid(
                "Inconsistent member identity or latest House".into(),
            ));
        }
        if history.memberships.is_empty()
            || history
                .memberships
                .iter()
                .any(|m| ![1, 2].contains(&m.house))
        {
            return Err(ImportError::Invalid("Invalid membership history".into()));
        }
        let periods = history.service(term, as_of, current)?;
        Ok(Self {
            profile,
            current,
            periods,
        })
    }
}

pub(crate) fn validate_configured_term(
    term: NaiveDate,
    stored: impl IntoIterator<Item = NaiveDate>,
) -> Result<()> {
    if stored.into_iter().any(|date| date != term) {
        return Err(ImportError::Invalid(
            "This database contains another term; rollover requires an explicit migration".into(),
        ));
    }
    Ok(())
}

