 /// Contains the configuration parameters for this project
 pub mod config;
+
+/// Importing and refreshing Parliament evidence.
+pub mod imports;
use crate::imports::{
    config::WhatsAppConfig,
    core::{ImportError, Result, ports::Notifications},
};
use anyhow::Context;
use serde_json::json;
use std::time::Duration;

pub(crate) struct WhatsApp {
    client: reqwest::Client,
    config: WhatsAppConfig,
    token: String,
}
impl WhatsApp {
    pub fn new(config: WhatsAppConfig) -> anyhow::Result<Self> {
        let token = std::env::var(&config.token_env)
            .context("WhatsApp token environment variable is missing")?;
        anyhow::ensure!(!token.is_empty(), "WhatsApp token is empty");
        anyhow::ensure!(
            config.api_version.starts_with('v')
                && config.api_version[1..]
                    .chars()
                    .all(|c| c.is_ascii_digit() || c == '.'),
            "Invalid Graph API version"
        );
        anyhow::ensure!(
            !config.phone_number_id.is_empty()
                && config.phone_number_id.chars().all(|c| c.is_ascii_digit()),
            "Invalid WhatsApp sender ID"
        );
        Ok(Self {
            client: reqwest::Client::builder()
                .timeout(Duration::from_secs(30))
                .build()?,
            config,
            token,
        })
    }
}
impl Notifications for WhatsApp {
    async fn deliver(&self, message: &str) -> Result<()> {
        let url = format!(
            "https://graph.facebook.com/{}/{}/messages",
            self.config.api_version, self.config.phone_number_id
        );
        let response = self
            .client
            .post(url)
            .bearer_auth(&self.token)
            .json(&json!({
                "messaging_product":"whatsapp", "to":self.config.recipient, "type":"template",
                "template": {"name":self.config.template,"language":{"code":self.config.language},
                    "components":[{"type":"body","parameters":[{"type":"text","text":message}]}]}
            }))
            .send()
            .await
            .map_err(|e| ImportError::source_failure("WhatsApp transport failed", e))?;
        let status = response.status();
        response.error_for_status().map_err(|e| {
            ImportError::source_failure(format!("WhatsApp returned HTTP {}", status.as_u16()), e)
        })?;
        Ok(())
    }
}
use chrono::NaiveDate;
use serde::Deserialize;
use std::{net::SocketAddr, path::PathBuf};

/// Optional runtime configuration for application-owned imports.
#[derive(Clone, Deserialize)]
pub struct ImportConfig {
    /// The single Parliament supported by this database.
    pub term_start: NaiveDate,
    /// Interpreter containing the API-only Python package, relative to the working directory.
    pub python: PathBuf,
    /// Python package directory, relative to the working directory.
    pub source_directory: PathBuf,
    /// Separate operator listener. Use loopback unless an access token is configured.
    pub admin_bind: SocketAddr,
    /// Environment variable holding a bearer token for operator commands.
    pub admin_token_env: Option<String>,
    /// Run the daily declaration check inside the application.
    #[serde(default = "enabled")]
    pub automatic_refresh: bool,
    /// Optional application notification interval. No interval means no notifications.
    pub notification_interval_seconds: Option<i64>,
    /// Official WhatsApp delivery configuration. Credentials stay in the environment.
    pub whatsapp: Option<WhatsAppConfig>,
}
fn enabled() -> bool {
    true
}

/// A template with one body text parameter must be approved for this sender.
#[derive(Clone, Deserialize)]
pub struct WhatsAppConfig {
    /// Supported Graph API version selected during sender setup, e.g. vXX.Y.
    pub api_version: String,
    /// Business Platform sender phone number identifier.
    pub phone_number_id: String,
    /// Recipient phone number in international digit format.
    pub recipient: String,
    /// Approved template name.
    pub template: String,
    /// Template language code.
    pub language: String,
    /// Environment variable holding the access token.
    pub token_env: String,
}

