                "".into(),
                "".into(),
            ))
        );

        assert_eq!(
            ranked.get(1).unwrap(),
            &Entity::from(&ParliamentMember::new(
                "hades".into(),
                1,
                "".into(),
                "".into(),
            ))
        );
    }

