                SearchSimilarity::from(4_f32),
            ),
            (
                Funder::new("canna ltd".into(), FunderKind::Company),
                SearchSimilarity::from(2_f32),
            ),
        ];
        let mps = vec![
            (
                ParliamentMember::new("johnny larner".into(), 1, "".into(), "".into()),
                SearchSimilarity::from(4_f32),
            ),
            (
                ParliamentMember::new("hades".into(), 1, "".into(), "".into()),
