mod test_scaffolding {
    use sqlx::PgPool;

    #[sqlx::test(migrations = "../db/migrations")]
    async fn migrations_work(pool: PgPool) -> sqlx::Result<()> {
        let res = sqlx::query!("SELECT name FROM members")
            .fetch_all(&pool)
            .await;
        assert!(res.is_ok());
        Ok(())
    }

    #[sqlx::test(
        migrations = "../db/migrations",
        fixtures(
            "../../../../db/fixtures/add_members.sql",
            "../../../../db/fixtures/add_declarations_and_funding_entries.sql"
        )
    )]
    async fn fixtures_work(pool: PgPool) -> sqlx::Result<()> {
        let res = sqlx::query!("SELECT name FROM members")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        let res = sqlx::query!("SELECT * FROM declarations")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        let res = sqlx::query!("SELECT * FROM funders")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        let res = sqlx::query!("SELECT * FROM funding_entries")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        Ok(())
    }
}
use std::sync::Arc;

use crate::{
    config::Config,
    domain::services::entity_search::Service as EntitySearchService,
    inbound::http::{routes::routes, state::AppState},
    outbound::ExposedDatabase,
};

/// Starts an `exposed` HTTP server
pub async fn serve_exposed(config: &Config) -> anyhow::Result<()> {
    let db = ExposedDatabase::new(&config.connection_string).await;
    let service = EntitySearchService::new(db.clone(), db);

    let state = AppState {
        entity_search_service: Arc::new(service),
    };
    let router = routes().with_state(state);

    let port = config.port;
    let listener = tokio::net::TcpListener::bind(format!("0.0.0.0:{port}"))
        .await
        .unwrap();

    let _ = axum::serve(listener, router).await?;

    Ok(())
}

