pub(crate) struct Page<T> {
    pub entries: Vec<T>,
    pub next: Option<usize>,
}

pub(crate) trait MemberSource: Send + Sync {
    fn profiles(
        &self,
        term: NaiveDate,
        as_of: NaiveDate,
        current: bool,
